mapper.select:
SELECT m.id, m.source_type, m.scene_code, m.title, m.content_type, m.category_id, c.name AS category_name, m.sender_user_id, m.recipient_scope_type, m.total_count, m.success_count, m.fail_count, m.status, m.recalled_at, m.created_at, m.updated_at, m.created_by, m.updated_by FROM in_app_message m LEFT JOIN in_app_message_category c ON c.id = m.category_id
AND m.status = #{query.status}
AND m.source_type = #{query.sourceType}
AND m.recipient_scope_type = #{query.recipientScopeType}
AND m.category_id = #{query.categoryId}
AND m.title LIKE CONCAT(#{query.title}, '%')
ORDER BY m.created_at DESC

mapper.update:
UPDATE in_app_message
SET status        = #{status},
    success_count = #{deliveredCount},
    total_count   = #{deliveredCount}
WHERE id = #{id}

UPDATE in_app_message
SET status         = 'RECALLED',
    recalled_at    = #{recalledAt},
    recall_user_id = #{recallUserId}
WHERE id = #{id}
  AND status IN ('SUCCESS', 'PARTIAL', 'NO_RECIPIENTS')
